[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$PolicyPath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$p=(Resolve-Path $PolicyPath).Path;if(-not $p.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'PolicyPath must remain under project root.'};$x=Get-Content $p -Raw -Encoding UTF8|ConvertFrom-Json;$issues=[Collections.Generic.List[string]]::new();if($x.recordType -ne 'WebPageStudioCachePolicy'){$issues.Add('RECORD_TYPE')};foreach($r in @($x.routes)){if($r.renderPolicy -eq 'prerender' -and $r.keyStrategy -eq 'none'){$issues.Add("PRERENDER_KEY_MISSING_$($r.routeId)")};if($r.cacheControl.private -and $r.renderPolicy -eq 'prerender'){$issues.Add("PRIVATE_PRERENDER_$($r.routeId)")};if($r.cacheControl.staleWhileRevalidateSeconds -gt 0 -and $r.fallback -eq 'none'){$issues.Add("SWR_FALLBACK_MISSING_$($r.routeId)")};if($r.renderPolicy -eq 'dynamic' -and $r.keyStrategy -eq 'immutable-hash'){$issues.Add("DYNAMIC_IMMUTABLE_KEY_$($r.routeId)")}};if($x.invalidation.onMutation -eq 'mark-stale' -and $x.invalidation.recovery -eq 'block'){$issues.Add('STALE_RECOVERY_BLOCKS')};if($x.evidence.runtimeStatus -eq 'runtime-passed'){$issues.Add('UNSUPPORTED_RUNTIME_CLAIM')};$o=[ordered]@{validator='web-cache-policy';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);runtimeStatus=[string]$x.evidence.runtimeStatus;nonClaims=@('Static policy validation does not prove CDN invalidation or multi-node coherence')};$o|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
